package net.officefloor.hq.app.dashboard;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.client.ClientRepository;
import net.officefloor.hq.app.invoice.InvoiceRepository;
import net.officefloor.hq.app.invoice.InvoiceStatus;
import net.officefloor.hq.app.project.ProjectRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class DashboardService {

    private final ClientRepository clients;
    private final ProjectRepository projects;
    private final InvoiceRepository invoices;

    public DashboardService(ClientRepository clients, ProjectRepository projects, InvoiceRepository invoices) {
        this.clients = clients;
        this.projects = projects;
        this.invoices = invoices;
    }

    /** Counts of clients and projects, and the total still owed (sum of sent, unpaid invoices). */
    @Transactional(readOnly = true)
    public DashboardResponse summary() {
        BigDecimal outstanding = invoices.sumAmountByStatus(InvoiceStatus.SENT).setScale(2, RoundingMode.HALF_UP);
        return new DashboardResponse(clients.count(), projects.count(), outstanding);
    }
}
package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface InvoiceRepository extends JpaRepository<Invoice, Long> {

    List<Invoice> findByProjectIdOrderById(Long projectId);

    /** All invoices across every project, with their project loaded in the same query. */
    @Query("SELECT i FROM Invoice i JOIN FETCH i.project ORDER BY i.id")
    List<Invoice> findAllWithProject();

    /** Invoices across every project at the given status, with their project loaded in the same query. */
    @Query("SELECT i FROM Invoice i JOIN FETCH i.project WHERE i.status = :status ORDER BY i.id")
    List<Invoice> findAllWithProjectByStatus(InvoiceStatus status);

    /** Sum of the amounts of all invoices with the given status (zero when there are none). */
    @Query("SELECT COALESCE(SUM(i.amount), 0) FROM Invoice i WHERE i.status = :status")
    BigDecimal sumAmountByStatus(InvoiceStatus status);
}
